//! Emoji catalogue and search (plan K4).
//!
//! `data/emoji.tsv` is generated by `dict-build/build_emoji.py` from Unicode
//! `emoji-test.txt` (group + English name) and CLDR annotations (Thai name). Searching matches
//! either language, so typing "ยิ้ม" or "smile" finds the same faces.

#[derive(Debug, Clone)]
pub struct Emoji {
    pub char: String,
    pub group: String,
    pub en: String,
    pub th: String,
}

pub struct EmojiIndex {
    entries: Vec<Emoji>,
}

impl EmojiIndex {
    pub fn parse(tsv: &str) -> EmojiIndex {
        let mut entries = Vec::new();
        for line in tsv.lines() {
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() < 3 {
                continue;
            }
            entries.push(Emoji {
                char: parts[0].to_string(),
                group: parts[1].to_string(),
                en: parts[2].to_string(),
                th: parts.get(3).unwrap_or(&"").to_string(),
            });
        }
        EmojiIndex { entries }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Case-insensitive substring match over the English and Thai names.
    pub fn search(&self, query: &str) -> Vec<&Emoji> {
        let needle = query.trim().to_lowercase();
        if needle.is_empty() {
            return Vec::new();
        }
        self.entries
            .iter()
            .filter(|emoji| emoji.en.to_lowercase().contains(&needle) || emoji.th.contains(&needle))
            .take(30)
            .collect()
    }

    pub fn by_group(&self, group: &str) -> Vec<&Emoji> {
        self.entries
            .iter()
            .filter(|emoji| emoji.group == group)
            .take(30)
            .collect()
    }
}
